"""Brute-force solvers for ThreeSat (3-SAT) and NaeThreeSat (NAE-3-SAT).

Written from the definitions in problems.py.  These are exponential and are
only meant for checking small instances.
"""

from __future__ import annotations

from itertools import product
from typing import Dict, Iterable, List


def _assignments(num_vars: int) -> Iterable[tuple]:
    """Yield every truth assignment as a tuple of booleans, index 0 unused."""
    for bits in product((False, True), repeat=num_vars):
        # bits[i] is the value of variable i+1
        yield bits


def _lit_value(literal: int, bits: tuple) -> bool:
    value = bits[abs(literal) - 1]
    return value if literal > 0 else not value


def solve_three_sat(instance: Dict) -> bool:
    """True iff some assignment makes every clause have a true literal."""
    m = instance["num_vars"]
    clauses: List[List[int]] = instance["clauses"]
    for bits in _assignments(m):
        if all(any(_lit_value(lit, bits) for lit in clause) for clause in clauses):
            return True
    return False


def solve_nae_three_sat(instance: Dict) -> bool:
    """True iff some assignment makes every clause not all equal."""
    m = instance["num_vars"]
    clauses: List[List[int]] = instance["clauses"]
    for bits in _assignments(m):
        ok = True
        for clause in clauses:
            values = [_lit_value(lit, bits) for lit in clause]
            if all(values) or not any(values):
                ok = False
                break
        if ok:
            return True
    return False
