from itertools import combinations, product
from solvers import solve_three_sat, solve_nae_three_sat
from reduce import reduce

# all possible clauses over m vars: 3 distinct vars, each sign
def all_clauses(m):
    out = []
    for vars_ in combinations(range(1, m+1), 3):
        for signs in product((1,-1), repeat=3):
            out.append([s*v for s,v in zip(signs, vars_)])
    return out

def search(m, max_clauses):
    cls = all_clauses(m)
    found = []
    # search multisets up to max_clauses using index combos with repetition
    from itertools import combinations_with_replacement
    for r in range(1, max_clauses+1):
        for combo in combinations_with_replacement(range(len(cls)), r):
            inst = {"num_vars": m, "clauses": [cls[i] for i in combo]}
            a = solve_three_sat(inst)
            red = reduce(inst)
            b = solve_nae_three_sat(red)
            if a != b:
                found.append((inst, a, red, b))
                return found
    return found

for m in range(3, 5):
    for mc in range(1, 4):
        f = search(m, mc)
        if f:
            print("COUNTEREXAMPLE m=%d maxc=%d" % (m, mc))
            for inst,a,red,b in f:
                print("inst:", inst, "3sat:", a)
                print("red :", red, "nae:", b)
            raise SystemExit
        print("no CE m=%d maxc=%d" % (m, mc))
print("none found")
